INSERT INTO `export_recipes` VALUES(1, 'Imperial King Crab Gratin', 'Baked King Crab Legs with Gruyere', 'An elegant baked masterpiece featuring wild Alaska king crab meat cooked in rich garlic white wine reduction, blanketed in flame-broiled artisan gruyère cheese and finished with a golden breadcrumb crust.', 'Advanced', 45, 'https://images.unsplash.com/photo-1599487488170-d11ec9c172f0?auto=format&fit=crop&w=800&q=80', 1, 'approved', NULL, '2026-06-06 15:36:44', '2026-06-07 13:46:26');
INSERT INTO `export_recipes` VALUES(2, 'Miyako Seared Black Grouper Tataki', 'Pan-Seared Black Grouper Medallions', 'Perfectly flash-seared Miyako deep sea black grouper fillet, sliced thin and dressed in hand-ground winter black truffle infusion and citrus juice. A masterclass in precision cooking.', 'Master Chef', 20, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?auto=format&fit=crop&w=800&q=80', 1, 'approved', NULL, '2026-06-06 15:36:44', '2026-06-07 13:46:26');
INSERT INTO `export_recipes` VALUES(3, 'Hiroshima Emperor Pearl Oyster Platter', 'Chilled Pearl Oysters with Sturgeon Caviar', 'A decadent, sweet and salty dish loaded with pristine sashimi-grade Hiroshima pearl oysters layered over ice-chilled cedar beds, crowned with sturgeon caviar.', 'Expert', 15, 'https://images.unsplash.com/photo-1611143669185-af224c5e3252?auto=format&fit=crop&w=800&q=80', 1, 'approved', NULL, '2026-06-06 15:36:44', '2026-06-07 13:46:26');
INSERT INTO `export_recipes` VALUES(5, 'Kombu Dashi Poached Giant Octopus', 'Simmered Octopus Tentacles in Kelp Broth', 'Slow-simmered whole premium Hokkaido octopus tentacles cooked for 4 hours in kelp tea, premium sake, and sweet mirin to achieve absolute tenderness.', 'Expert', 240, 'https://images.unsplash.com/photo-1615141982883-c7ad0e69fd62?auto=format&fit=crop&w=800&q=80', 1, 'approved', NULL, '2026-06-06 15:36:44', '2026-06-07 13:46:26');
