INSERT INTO `export_recipe_items` VALUES(1, 1, 'ingredient', '500g wild Alaska king crab legs', 0, 77);
INSERT INTO `export_recipe_items` VALUES(2, 1, 'ingredient', '2 tbsp unsalted butter', 1, NULL);
INSERT INTO `export_recipe_items` VALUES(3, 1, 'ingredient', '3 cloves garlic, minced', 2, NULL);
INSERT INTO `export_recipe_items` VALUES(4, 1, 'ingredient', '120ml dry white wine', 3, NULL);
INSERT INTO `export_recipe_items` VALUES(5, 1, 'ingredient', '200ml heavy cream', 4, NULL);
INSERT INTO `export_recipe_items` VALUES(6, 1, 'ingredient', '150g gruyère cheese, grated', 5, NULL);
INSERT INTO `export_recipe_items` VALUES(7, 1, 'ingredient', '50g panko breadcrumbs', 6, NULL);
INSERT INTO `export_recipe_items` VALUES(8, 1, 'ingredient', '1 tbsp fresh parsley, chopped', 7, NULL);
INSERT INTO `export_recipe_items` VALUES(9, 1, 'ingredient', 'Salt and white pepper to taste', 8, NULL);
INSERT INTO `export_recipe_items` VALUES(10, 1, 'step', 'Preheat oven to 200°C. Crack crab legs and extract meat, keeping shells intact.', 0, NULL);
INSERT INTO `export_recipe_items` VALUES(11, 1, 'step', 'In a pan, melt butter and sauté garlic until fragrant. Add white wine and reduce by half.', 1, NULL);
INSERT INTO `export_recipe_items` VALUES(12, 1, 'step', 'Stir in heavy cream and half the gruyère. Season with salt and white pepper.', 2, NULL);
INSERT INTO `export_recipe_items` VALUES(13, 1, 'step', 'Arrange crab meat in the shells or a baking dish. Pour sauce over the top.', 3, NULL);
INSERT INTO `export_recipe_items` VALUES(14, 1, 'step', 'Sprinkle remaining gruyère and panko breadcrumbs. Bake 10-12 mins until golden and bubbling.', 4, NULL);
INSERT INTO `export_recipe_items` VALUES(15, 1, 'step', 'Garnish with fresh parsley and serve immediately with lemon wedges.', 5, NULL);
INSERT INTO `export_recipe_items` VALUES(16, 2, 'ingredient', '300g black grouper fillet, skin-on', 0, 95);
INSERT INTO `export_recipe_items` VALUES(17, 2, 'ingredient', '1 tbsp black truffle oil', 1, NULL);
INSERT INTO `export_recipe_items` VALUES(18, 2, 'ingredient', '1 tsp yuzu citrus juice', 2, NULL);
INSERT INTO `export_recipe_items` VALUES(19, 2, 'ingredient', '1 tsp soy sauce', 3, NULL);
INSERT INTO `export_recipe_items` VALUES(20, 2, 'ingredient', '1 tsp sesame oil', 4, NULL);
INSERT INTO `export_recipe_items` VALUES(21, 2, 'ingredient', 'Shiso leaves for garnish', 5, NULL);
INSERT INTO `export_recipe_items` VALUES(22, 2, 'ingredient', 'Daikon radish, thinly sliced', 6, NULL);
INSERT INTO `export_recipe_items` VALUES(23, 2, 'ingredient', 'Sea salt flakes', 7, NULL);
INSERT INTO `export_recipe_items` VALUES(24, 2, 'step', 'Score the grouper skin in a crosshatch pattern. Pat dry and season with sea salt.', 0, NULL);
INSERT INTO `export_recipe_items` VALUES(25, 2, 'step', 'Sear skin-side down in a hot pan with sesame oil for 2-3 mins until crisp.', 1, NULL);
INSERT INTO `export_recipe_items` VALUES(26, 2, 'step', 'Flip and cook 1 min for rare. Transfer to a cutting board.', 2, NULL);
INSERT INTO `export_recipe_items` VALUES(27, 2, 'step', 'Slice thinly against the grain. Arrange on a plate with shiso and daikon.', 3, NULL);
INSERT INTO `export_recipe_items` VALUES(28, 2, 'step', 'Whisk truffle oil, yuzu juice, and soy sauce. Drizzle over the tataki.', 4, NULL);
INSERT INTO `export_recipe_items` VALUES(29, 2, 'step', 'Serve immediately at room temperature.', 5, NULL);
INSERT INTO `export_recipe_items` VALUES(30, 3, 'ingredient', '12 Hiroshima pearl oysters, shucked', 0, 216);
INSERT INTO `export_recipe_items` VALUES(31, 3, 'ingredient', '30g sturgeon caviar', 1, NULL);
INSERT INTO `export_recipe_items` VALUES(32, 3, 'ingredient', 'Ice-chilled cedar plank or serving tray', 2, NULL);
INSERT INTO `export_recipe_items` VALUES(33, 3, 'ingredient', '1 lemon, cut into wedges', 3, NULL);
INSERT INTO `export_recipe_items` VALUES(34, 3, 'ingredient', 'Mignonette sauce (shallot, vinegar, pepper)', 4, NULL);
INSERT INTO `export_recipe_items` VALUES(35, 3, 'ingredient', 'Fresh seaweed garnish', 5, NULL);
INSERT INTO `export_recipe_items` VALUES(36, 3, 'step', 'Shuck oysters carefully, preserving the liquor. Clean any shell fragments.', 0, NULL);
INSERT INTO `export_recipe_items` VALUES(37, 3, 'step', 'Arrange oysters on crushed ice over a cedar plank.', 1, NULL);
INSERT INTO `export_recipe_items` VALUES(38, 3, 'step', 'Top each oyster with a small spoonful of caviar.', 2, NULL);
INSERT INTO `export_recipe_items` VALUES(39, 3, 'step', 'Serve with lemon wedges and mignonette sauce on the side.', 3, NULL);
INSERT INTO `export_recipe_items` VALUES(40, 3, 'step', 'Garnish with fresh seaweed and serve immediately.', 4, NULL);
INSERT INTO `export_recipe_items` VALUES(57, 5, 'ingredient', '1.5kg giant octopus tentacles (Hokkaido preferred)', 0, 52);
INSERT INTO `export_recipe_items` VALUES(58, 5, 'ingredient', '2L kombu dashi (kelp broth)', 1, NULL);
INSERT INTO `export_recipe_items` VALUES(59, 5, 'ingredient', '120ml sake', 2, NULL);
INSERT INTO `export_recipe_items` VALUES(60, 5, 'ingredient', '60ml mirin', 3, NULL);
INSERT INTO `export_recipe_items` VALUES(61, 5, 'ingredient', '3 tbsp soy sauce', 4, NULL);
INSERT INTO `export_recipe_items` VALUES(62, 5, 'ingredient', '1 tbsp sugar', 5, NULL);
INSERT INTO `export_recipe_items` VALUES(63, 5, 'ingredient', 'Ginger slices (5-6 pieces)', 6, NULL);
INSERT INTO `export_recipe_items` VALUES(64, 5, 'ingredient', 'Sesame oil and shichimi togarashi to finish', 7, NULL);
INSERT INTO `export_recipe_items` VALUES(65, 5, 'step', 'Rinse octopus. Massage with coarse salt to remove slime. Rinse again.', 0, NULL);
INSERT INTO `export_recipe_items` VALUES(66, 5, 'step', 'Bring kombu dashi, sake, mirin, soy sauce, sugar, and ginger to a simmer.', 1, NULL);
INSERT INTO `export_recipe_items` VALUES(67, 5, 'step', 'Add octopus, cover with a drop-lid (otoshibuta). Simmer on low heat for 3-4 hours.', 2, NULL);
